:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #f0f0f5;
  --accent: #ffb347;
  --accent-2: #6c5ce7;
  --hunger: #ff6b6b;
  --happiness: #feca57;
  --energy: #48dbfb;
  --radius: 16px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: radial-gradient(circle at 20% 20%, #2e2e4a, var(--bg));
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
}

.game-board {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
  text-align: center;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--accent);
}

.pet-stage {
  display: flex;
  justify-content: center;
  padding: 12px 0;
}

/* Pixel pet drawn with CSS */
.pet {
  position: relative;
  width: 120px;
  height: 120px;
  image-rendering: pixelated;
}

.pet-body {
  position: absolute;
  inset: 10px;
  background: var(--accent-2);
  border-radius: 30% 30% 35% 35%;
  box-shadow:
    0 0 0 4px #4a3fc4,
    inset -8px -8px 0 rgba(0, 0, 0, 0.15);
}

.pet-eye {
  position: absolute;
  width: 16px;
  height: 16px;
  background: #fff;
  border-radius: 4px;
  top: 45px;
  box-shadow: inset 0 0 0 4px #1e1e2f;
}

.pet-eye.left { left: 28px; }
.pet-eye.right { right: 28px; }

.pet-mouth {
  position: absolute;
  width: 24px;
  height: 8px;
  background: #1e1e2f;
  border-radius: 0 0 12px 12px;
  bottom: 32px;
  left: 50%;
  transform: translateX(-50%);
}

/* Mood text */
.mood {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--accent);
  min-height: 1.5em;
}

/* Stats */
.stats {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.stat-label {
  display: flex;
  justify-content: space-between;
  font-size: 0.95rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.bar {
  height: 14px;
  background: #1a1a2e;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.5);
}

.bar-fill {
  height: 100%;
  border-radius: 8px;
  transition: width 0.3s ease;
}

.bar-fill.hunger { background: var(--hunger); }
.bar-fill.happiness { background: var(--happiness); }
.bar-fill.energy { background: var(--energy); }

/* Controls */
.controls {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: center;
}

button {
  flex: 1 1 100px;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 700;
  font-family: inherit;
  color: #1e1e2f;
  background: var(--accent);
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: transform 0.1s ease, background 0.2s ease, box-shadow 0.2s ease;
  box-shadow: 0 4px 0 #b97e2e;
}

button:hover {
  background: #ffc56e;
}

button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 3px;
}

button:active {
  transform: translateY(3px);
  box-shadow: 0 1px 0 #b97e2e;
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

@media (max-width: 360px) {
  .game-board { padding: 16px; }
  button { flex: 1 1 100%; }
  .stat-label { font-size: 0.9rem; }
}

'use strict';

const state = {
  hunger: 70,
  happiness: 70,
  energy: 70
};

const els = {
  hungerBar: document.getElementById('hunger-bar'),
  hungerValue: document.getElementById('hunger-value'),
  happinessBar: document.getElementById('happiness-bar'),
  happinessValue: document.getElementById('happiness-value'),
  energyBar: document.getElementById('energy-bar'),
  energyValue: document.getElementById('energy-value'),
  mood: document.getElementById('mood'),
  feed: document.getElementById('feed-btn'),
  play: document.getElementById('play-btn'),
  sleep: document.getElementById('sleep-btn')
};

const clamp = (v) => Math.max(0, Math.min(100, v));

function updateMood() {
  const avg = (state.hunger + state.happiness + state.energy) / 3;
  let mood;
  if (avg >= 75) mood = 'Ecstatic';
  else if (avg >= 55) mood = 'Happy';
  else if (avg >= 35) mood = 'Okay';
  else if (avg >= 15) mood = 'Sad';
  else mood = 'Miserable';
  els.mood.textContent = `Mood: ${mood}`;
}

function render() {
  els.hungerBar.style.width = state.hunger + '%';
  els.hungerValue.textContent = state.hunger;
  els.hungerBar.parentElement.setAttribute('aria-valuenow', state.hunger);

  els.happinessBar.style.width = state.happiness + '%';
  els.happinessValue.textContent = state.happiness;
  els.happinessBar.parentElement.setAttribute('aria-valuenow', state.happiness);

  els.energyBar.style.width = state.energy + '%';
  els.energyValue.textContent = state.energy;
  els.energyBar.parentElement.setAttribute('aria-valuenow', state.energy);

  updateMood();
}

function feed() {
  state.hunger = clamp(state.hunger + 20);
  state.energy = clamp(state.energy - 5);
  render();
}

function play() {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 15);
  state.hunger = clamp(state.hunger - 10);
  render();
}

function sleep() {
  state.energy = clamp(state.energy + 30);
  state.hunger = clamp(state.hunger - 10);
  render();
}

els.feed.addEventListener('click', feed);
els.play.addEventListener('click', play);
els.sleep.addEventListener('click', sleep);

render();
